import java.util.Scanner

fun main() {
    val n = readLine()!!.trim().toLong()
    var a = 1L
    var b = 2L
    var k = 0
    if (n < b) {
        println(0)
        return
    }
    while (true) {
        val c = a + b
        if (c > n || c < 0) break
        a = b
        b = c
        k++
    }
    println(k + 1)
}
